    {using var owner=new ProtectionFixture();var s=await Setup(owner);var before=await Snapshot(s);var raw=Bytes(Input());if(kind=="empty"){using var host=new WebApplicationFactory<Program>();var context=await host.Server.SendAsync(c=>{c.Request.Method="POST";c.Request.Path="/api/folders";c.Request.Headers.Authorization="Bearer "+RegistrationApiFixture.Token(s.Actor);c.Request.Headers["X-Cerberus-Vault-Access"]="";c.Request.ContentType="application/json";c.Request.Body=new MemoryStream(raw);c.Request.ContentLength=raw.Length;});Assert.Equal(status,context.Response.StatusCode);Assert.Contains("no-store",context.Response.Headers.CacheControl.ToString());}else{using var request=Request(s,raw,kind=="query"?"/api/folders?unexpected=1":"/api/folders");if(kind=="missing")request.Headers.Remove("X-Cerberus-Vault-Access");if(kind=="bad"){request.Headers.Remove("X-Cerberus-Vault-Access");request.Headers.TryAddWithoutValidation("X-Cerberus-Vault-Access","bad");}if(kind=="duplicate")request.Headers.TryAddWithoutValidation("X-Cerberus-Vault-Access",s.Access);using var r=await Gateway.Client.SendAsync(request);await Failure(r,status);}Assert.Equal(before,await Snapshot(s));}
