    [FunctionalTheory][InlineData(false)][InlineData(true)]
    public async Task GivenHttpCreatedFolder_WhenRotatingContent_ThenRequireCompleteInventoryAndPreserveEditedAt(bool complete)
    {
        using var owner=new ProtectionFixture();var s=await Setup(owner);var input=Input();using(var created=await Send(s,input))await Success<CreateFolderOutput>(created,201);var content=new List<ContentReplacement>{new("account",s.AccountId,1,Envelope(2))};if(complete)content.Add(new("folder",input.FolderId,1,Envelope(2)));var change=new ProtectionChange(s.AccountId,1,1,"rotate-content",owner.Rewrap(),content.ToArray());var raw=Bytes(change);
        using var challengeRequest=new HttpRequestMessage(HttpMethod.Post,"/api/vault/challenges"){Content=JsonContent.Create(new{operation="change-protection",requestHash=ProtocolBinary.Encode(SHA256.HashData(raw))})};challengeRequest.Headers.Authorization=new("Bearer",RegistrationApiFixture.Token(s.Actor));using var issued=await Gateway.Client.SendAsync(challengeRequest);Assert.Equal(HttpStatusCode.Created,issued.StatusCode);using var document=JsonDocument.Parse(await issued.Content.ReadAsStringAsync());var challenge=document.RootElement.GetProperty("data").GetProperty("challenge").Deserialize<VaultProofChallenge>(ProtectionFixture.Json)!;var before=await Snapshot(s);
        using var request=Request(s,raw,"/api/vault/protection");request.Method=HttpMethod.Put;request.Headers.Add("X-Cerberus-Challenge-Id",challenge.ChallengeId.ToString());request.Headers.Add("X-Cerberus-Proof",owner.Sign(challenge));using var response=await Gateway.Client.SendAsync(request);if(!complete){await Failure(response,400,"validation_failed");Assert.Equal(before,await Snapshot(s));}else{Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.True(response.Headers.CacheControl?.NoStore);await using var db=fixture.Context();var folder=await db.Folders.SingleAsync(x=>x.PublicId==input.FolderId);Assert.Equal(2,folder.Revision);Assert.Equal(Bytes(content[1].Envelope),folder.Envelope);Assert.Equal(Normalize(input.EditedAt),folder.EditedAt);Assert.True((await db.VaultUnlockChallenges.SingleAsync(x=>x.PublicId==challenge.ChallengeId)).Consumed);using var stale=await Send(s,Input());await Failure(stale,403);}
    }
    private sealed record State(Guid Actor,Guid AccountId,long InternalId,string Access);
    private async Task<State> Setup(ProtectionFixture client)
    {var actor=Guid.NewGuid();fixture.Users[actor+"@example.test"]=new(actor,"fixture-password");await using var db=fixture.Context();var account=new Account{PublicId=Guid.NewGuid(),HeimdallPublicId=actor,DetailsEnvelope=Bytes(Envelope())};db.Accounts.Add(account);await db.SaveChangesAsync();var access=ProtocolBinary.Encode(RandomNumberGenerator.GetBytes(32));OpaqueAccessHandle.TryHash(access,out var verifier);db.VaultProtections.Add(new(){AccountId=account.Id,Material=Bytes(client.Material)});db.VaultAccessSessions.Add(new(){AccountId=account.Id,HandleVerifier=verifier,IssuedAt=DateTimeOffset.UtcNow.AddMinutes(-1),ExpiresAt=DateTimeOffset.UtcNow.AddHours(1),PolicyRevision=1,RevocationGeneration=1});await db.SaveChangesAsync();return new(actor,account.PublicId,account.Id,access);}
    private async Task<VaultFolder> Folder(State s,long? parent=null){var f=new VaultFolder{PublicId=Guid.NewGuid(),AccountId=s.InternalId,ParentFolderId=parent,Envelope=Bytes(Envelope()),EditedAt=DateTimeOffset.UnixEpoch};await using var db=fixture.Context();db.Folders.Add(f);await db.SaveChangesAsync();return f;}
    private async Task<Profile> Profile(State s,ProtectionFixture owner,ProtectionFixture scoped,VaultFolder? folder=null,string mode="Master")
    {var id=Guid.NewGuid();var input=new ProfileCreateInput(id,Envelope(),new(mode,scoped.Material.UnlockVerifier,owner.Wrap(s.AccountId,"profile",id,s.Actor),mode=="PerProfile"?scoped.Material.PasswordWrapper:null),DateTimeOffset.UnixEpoch,[],folder is null?[]:[folder.PublicId],[]);using var request=Request(s,Bytes(input),"/api/profiles");using var r=await Gateway.Client.SendAsync(request);Assert.Equal(HttpStatusCode.Created,r.StatusCode);await using var db=fixture.Context();return await db.Profiles.AsNoTracking().SingleAsync(x=>x.PublicId==id);}
    private async Task<string> Open(State s,Profile p,ProtectionFixture scoped)
    {var raw=Bytes(new{expectedRevision=1});using var challengeRequest=Request(s,Bytes(new{expectedRevision=1,requestHash=ProtocolBinary.Encode(SHA256.HashData(raw))}),"/api/profiles/"+p.PublicId+"/access/challenges");challengeRequest.Headers.Remove("X-Cerberus-Vault-Access");using var issued=await Gateway.Client.SendAsync(challengeRequest);var challenge=(await Success<IssueProfileAccessChallengeOutput>(issued,201)).Challenge;using var open=Request(s,raw,"/api/profiles/"+p.PublicId+"/access");open.Headers.Remove("X-Cerberus-Vault-Access");open.Headers.Add("X-Cerberus-Challenge-Id",challenge.ChallengeId.ToString());open.Headers.Add("X-Cerberus-Proof",scoped.Sign(challenge));using var response=await Gateway.Client.SendAsync(open);return (await Success<OpenProfileAccessOutput>(response,200)).VaultAccess;}
